#!/usr/bin/env bash
# lib.sh - shared helpers for the v9 rollout scripts (V9_DESIGN.md section 6).
#
# Sourced, never run. Loads, in order:
#   deploy/v8/deployment.env   every v8 ID (generated by scripts/v8, read-only here)
#   deploy/v9/multisig.env     the 2-of-3 UpgradeCap multisig (00_multisig.sh)
#   deploy/v9/deployment.env   v9 IDs: PKG_V9, COUNCIL, ... (02/04 append to it)
#
# The CLI must be >= testnet-v1.83.1: 1.74.0 cannot talk to testnet protocol 140.
# Override with SUI=/path/to/sui if it is not first on PATH.

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
V8_ENV="$REPO/deploy/v8/deployment.env"
V9_DIR="${V9_DIR:-$REPO/deploy/v9}"   # override only to rehearse with throwaway keys
MS_ENV="$V9_DIR/multisig.env"
V9_ENV="$V9_DIR/deployment.env"
PUBLISHER="0xb87fb2af21e29dd292d5b557b92d95a544794a589620f4b437f2247f075d6a1e"
SUI="${SUI:-$(command -v sui || true)}"
[ -x "$HOME/sui-cli/1.83.1/sui" ] && [ -z "${SUI_PINNED:-}" ] && SUI="$HOME/sui-cli/1.83.1/sui"
MIN_CLI="1.83.1"

say()  { echo; echo "=== $* ==="; }
die()  { echo "FATAL: $*" >&2; exit 1; }

# shellcheck disable=SC1090
[ -f "$V8_ENV" ] && . "$V8_ENV" || die "missing $V8_ENV"
# shellcheck disable=SC1090
[ -f "$MS_ENV" ] && . "$MS_ENV"
# shellcheck disable=SC1090
[ -f "$V9_ENV" ] && . "$V9_ENV"
mkdir -p "$V9_DIR"

require_cli() {
  [ -n "$SUI" ] && [ -x "$SUI" ] || die "sui CLI not found (set SUI=...)"
  local v; v=$("$SUI" --version | awk '{print $2}' | cut -d- -f1)
  if [ "$(printf '%s\n%s\n' "$MIN_CLI" "$v" | sort -V | head -1)" != "$MIN_CLI" ]; then
    die "sui CLI $v is older than $MIN_CLI (testnet runs protocol 140)"
  fi
  [ "$("$SUI" client active-env)" = "testnet" ] || die "active env is not testnet"
}

require_publisher() {
  local a; a=$("$SUI" client active-address)
  [ "$a" = "$PUBLISHER" ] || die "active address is $a, expected publisher $PUBLISHER"
}

require_multisig() {
  [ -n "${UPGRADE_MULTISIG:-}" ] && [ -n "${MS_PKS:-}" ] && [ -n "${MS_WEIGHTS:-}" ] && [ -n "${MS_THRESHOLD:-}" ] \
    || die "no multisig recorded; run scripts/v9/00_multisig.sh first"
}

# Owner of an object as "AddressOwner:0x.." / "Shared" / "ObjectOwner:0x.." via the CLI.
object_owner() {
  "$SUI" client object "$1" --json | python3 -c '
import json,sys
o=json.load(sys.stdin).get("owner")
if isinstance(o,dict):
    k=next(iter(o)); v=o[k]
    print(k+":"+(v if isinstance(v,str) else json.dumps(v)))
else:
    print(o)'
}

# Total SUI balance in MIST, via GraphQL (the CLI's balance JSON shape changes
# between releases; this query is the one the plugin and the gas checks use).
GRAPHQL_URL="${GRAPHQL_URL:-https://graphql.testnet.sui.io/graphql}"
sui_balance() {
  curl -sS --max-time 20 "$GRAPHQL_URL" -H 'content-type: application/json' \
    -d "{\"query\":\"{ address(address: \\\"$1\\\") { balance(coinType: \\\"0x2::sui::SUI\\\") { totalBalance } } }\"}" \
  | python3 -c '
import json,sys
d=json.load(sys.stdin)
b=((d.get("data") or {}).get("address") or {}).get("balance") or {}
print(int(b.get("totalBalance") or 0))'
}

# Free, unsigned simulation of one Move call as any sender (dev-inspect: no
# signature, no gas, nothing executes). Prints "success" or
# "abort:<module>::<function>:<code>" (or "error:<first line>").
#   inspect_outcome <sender> <package> <module> <function> [args...]
inspect_outcome() {
  local sender="$1" pkg="$2" mod="$3" fn="$4"; shift 4
  local a=(client call --package "$pkg" --module "$mod" --function "$fn")
  [ $# -gt 0 ] && a+=(--args "$@")
  "$SUI" "${a[@]}" --sender "$sender" --dev-inspect 2>&1 | python3 -c '
import re,sys
t=sys.stdin.read()
m=re.search(r"execution status: (\w+)", t)
if m and m.group(1)=="success": print("success"); sys.exit()
a=re.search(r"MoveAbort\(MoveLocation \{ module: ModuleId \{ address: \w+, name: Identifier\(\"(\w+)\"\) \}.*?function_name: Some\(\"(\w+)\"\) \}, (\d+)\)", t)
if a: print(f"abort:{a.group(1)}::{a.group(2)}:{a.group(3)}"); sys.exit()
first=next((l for l in t.splitlines() if l.strip()), "no output")
print("error:"+first[:160])'
}

# Return value (JSON) of a view function, by dev-inspect. Empty on abort.
#   inspect_value <package> <module> <function> [args...]
inspect_value() {
  local pkg="$1" mod="$2" fn="$3"; shift 3
  local a=(client call --package "$pkg" --module "$mod" --function "$fn")
  [ $# -gt 0 ] && a+=(--args "$@")
  "$SUI" "${a[@]}" --sender "$PUBLISHER" --dev-inspect --json 2>/dev/null | python3 -c '
import json,sys
try:
    d=json.load(sys.stdin); print(json.dumps(d["command_outputs"][0]["returnValues"][0]["json"]))
except Exception:
    print("")'
}

# Is $1 a Move package on-chain that contains the v9 quorum module?
check_v9_package() {
  curl -sS --max-time 20 "$GRAPHQL_URL" -H 'content-type: application/json' \
    -d "{\"query\":\"{ object(address: \\\"$1\\\") { asMovePackage { version modules { nodes { name } } } } }\"}" \
  | python3 -c '
import json,sys
p=((json.load(sys.stdin).get("data") or {}).get("object") or {}).get("asMovePackage")
if not p: sys.exit("FATAL: not a Move package on-chain")
mods=[m["name"] for m in p["modules"]["nodes"]]
if "quorum" not in mods: sys.exit("FATAL: package has no quorum module: %s" % mods)
print("package version", p["version"], "modules:", " ".join(mods))'
}

# Append KEY=VALUE to deploy/v9/deployment.env unless that exact line is there.
record() {
  [ -f "$V9_ENV" ] || printf '# v9 deployment - GENERATED by scripts/v9. Do not hand-edit.\n' > "$V9_ENV"
  grep -qx "export $1=$2" "$V9_ENV" || echo "export $1=$2" >> "$V9_ENV"
  export "$1=$2"
}

# Typed confirmation for irreversible steps. Bypass only with CONFIRM=<phrase>.
confirm() {
  local phrase="$1"
  if [ "${CONFIRM:-}" = "$phrase" ]; then return 0; fi
  [ -t 0 ] || die "non-interactive: re-run with CONFIRM='$phrase' to proceed"
  echo
  echo "Type exactly:  $phrase"
  read -r answer
  [ "$answer" = "$phrase" ] || die "confirmation did not match; nothing was done"
}

# Never let a Windows-written Move.lock reach the Linux CLI (see scripts/v8/01_publish.sh).
check_move_lock() {
  if grep -q "subdir = '.*\\\\" "$REPO/move/Move.lock" 2>/dev/null; then
    die "move/Move.lock has Windows path separators; restore with: git checkout HEAD -- move/Move.lock"
  fi
}
